contract InvMutTest {
    C c;
    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other, uint256 burnAmount) public {
        require(other != address(this));
        uint256 balOtherBefore = c.balanceOf(other); if (__ESBMC_reverted()) return;
        uint256 balOwnerBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        require(balOwnerBefore >= burnAmount);

        bool reverted;
        c.burn(burnAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted || (c.balanceOf(other) == balOtherBefore && c.balanceOf(address(this)) == balOwnerBefore - burnAmount));
    }

    receive() external payable {}
}

